import { roomRuleset, type DeckDefinition, type DeckOverride } from './deck';

const slug = (text: string) =>
  text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

function roomDeck(room: string, overrides?: DeckOverride[]): DeckDefinition {
  return { id: slug(room), name: room, build: roomRuleset({ room }), overrides };
}

/**
 * The slideshows, in sidebar order. Each is generated by a ruleset; add
 * `overrides` to hand-edit one. Examples:
 *
 *   roomDeck('Grand Ballroom', [
 *     // Show the Holding slide again right after a session's Standard slide.
 *     { op: 'insert', slideId: 'static:holding', after: 'recAbC123:standard' },
 *     // Drop one session's SHRM slide.
 *     { op: 'remove', key: 'recAbC123:shrm' },
 *     // Put the keynote first.
 *     { op: 'move', key: 'recKeyNote:upcoming', after: 'static:holding@before:recFirst' },
 *   ]),
 *
 * Keys: session slides use their SlideId (`recXXXX:upcoming`); separators use
 * `static:holding@before:<sessionId>` or `static:holding@end`.
 */
export const DECKS: DeckDefinition[] = [
  roomDeck('Grand Ballroom'),
  roomDeck('Empire East'),
  roomDeck('Empire West'),
  roomDeck('Gallery I'),
  roomDeck('Gallery II'),
];

export const deckById = (id: string | null) => DECKS.find((d) => d.id === id) ?? null;
